<script setup lang="ts">
import AdminConsole from '../console/AdminConsole.vue'
import ConsoleDrawer from '../console/ConsoleDrawer.vue'
import ConsoleDiscardChangesDialog from '../console/ConsoleDiscardChangesDialog.vue'
import ConsoleQueryButton from '../console/ConsoleQueryButton.vue'
import ConsumerIdentity from './ConsumerIdentity.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleListFilters from '@orangezh1/qisvc-console-ui/components/ConsoleListFilters'
import ConsoleListSearch from '@orangezh1/qisvc-console-ui/components/ConsoleListSearch'
import {dateTime} from '../../utils/update-center'

type Sale={providerLabel?:string;paymentId?:string;paymentSequence?:number;currentPayment?:boolean;legacyFullRefund?:boolean;requestedCents?:number|null;id:string;orderId:string;sequence:number;previousId:string|null;source:string;state:string;reason:string;reviewReason:string|null;reviewedAt:string|null;createdAt:string;succeededAt:string|null;payerRefundCents:number|null;payerTotalCents:number|null;amountCents:number;currency:string;lastError:string|null;user:{id:string;nickname:string|null;avatar:string|null}}
type Detail=Sale&{canReview:boolean;canReject:boolean;canApprove:boolean;canRetry:boolean;approveUnavailableReason:string|null;retryUnavailableReason:string|null;refundEffect:string;orderName:string|null;orderKind:string|null;remainingRequestedCents:number|null;payerRefundedCents:number|null;history:Sale[]}
type Listing={providers?:{key:string;label:string}[];items:Sale[];total:number;page:number;pageSize:number;applicationKey:string|null;applications:{key:string;name:string}[]}
const states:Record<string,string>={APPLIED:'待审核',REJECTED:'已拒绝',PENDING:'待提交渠道',PROCESSING:'渠道处理中',ABNORMAL:'渠道异常',CLOSED:'退款已关闭',SUCCESS:'退款成功'},sources:Record<string,string>={consumer:'用户申请',admin:'后台主动退款',compensation:'异常补偿'}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/after-sales'
const q=ref(''),state=ref('all'),provider=ref('all'),applicationKey=ref(''),page=ref(1),pageSize=ref(20),applied=reactive({q:'',state:'all',provider:'all'}),loadAction=ref<string|null>(null)
const params=()=>new URLSearchParams({q:applied.q,state:applied.state,...(applied.provider==='all'?{}:{provider:applied.provider}),page:String(page.value),pageSize:String(pageSize.value),...(applicationKey.value?{applicationKey:applicationKey.value}:{})})
const initial=await useAsyncData<Listing>('after-sales:'+auth.session.value?.id+':'+tenantId,(_nuxt,{signal})=>auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal}))
const rows=ref<Listing>(initial.data.value||{items:[],total:0,page:1,pageSize:20,applicationKey:null,applications:[]}),error=ref(initial.error.value?.message||'')
applicationKey.value=rows.value.applicationKey||''
const modal=ref(false),target=ref<Sale|null>(null),detail=ref<Detail|null>(null),detailBusy=ref(false),detailSource=ref(''),detailError=ref('')
const action=ref<'approve'|'reject'|'retry'|null>(null),actionTarget=ref<{id:string;applicationKey:string}|null>(null),reason=ref(''),actionError=ref(''),mutation=ref(false),discard=useDiscardChanges(()=>mutation.value)
const actionTitle=computed(()=>action.value==='approve'?'同意退款申请':action.value==='reject'?'拒绝退款申请':'重试已关闭的退款')
const columns=[{accessorKey:'id',header:'售后 / 原订单'},{accessorKey:'user',header:'客户'},{accessorKey:'providerLabel',header:'支付方式'},{accessorKey:'source',header:'来源'},{accessorKey:'state',header:'售后状态'},{accessorKey:'requestedCents',header:'申请 / 实退'},{accessorKey:'createdAt',header:'申请时间'},{id:'actions',header:'操作'}]
const money=(n:number|null|undefined)=>!Number.isSafeInteger(n)||n==null||n<0?'尚未确认':'¥'+Math.trunc(n/100)+'.'+String(n%100).padStart(2,'0')
const refunded=(row:Sale)=>row.state==='SUCCESS'?money(row.payerRefundCents):'—'
const permitted=(value:'approve'|'reject'|'retry')=>!!detail.value&&(value==='approve'?detail.value.canApprove:value==='reject'?detail.value.canReject:detail.value.canRetry)
let alive=true,listSequence=0,detailSequence=0,listController:AbortController|undefined,detailController:AbortController|undefined
const lifetime=new AbortController()
async function load(source:string){listController?.abort();listController=new AbortController();const number=++listSequence;loadAction.value=source;error.value='';try{const value=await auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,listController.signal])});if(alive&&number===listSequence){rows.value=value;page.value=value.page;applicationKey.value=value.applicationKey||''}}catch(e:any){if(alive&&number===listSequence&&!listController.signal.aborted)error.value=e.message||'售后订单读取失败'}finally{if(alive&&number===listSequence)loadAction.value=null}}
function filter(source:'search'|'reset'){if(source==='reset'){q.value='';state.value='all';provider.value='all'}applied.q=q.value.trim();applied.state=state.value;applied.provider=provider.value;page.value=1;void load(source)}
function setPage(value:number){if(page.value!==value){page.value=value;void load('page')}}
function setPageSize(value:number){pageSize.value=value;page.value=1;void load('page')}
async function readDetail(source:string){if(!target.value||!applicationKey.value)return;detailController?.abort();detailController=new AbortController();const number=++detailSequence,id=target.value.id,key=applicationKey.value;detailBusy.value=true;detailSource.value=source;detailError.value='';try{const value=await auth.api<Detail>(endpoint+'/'+encodeURIComponent(key)+'/'+id,'GET',undefined,{signal:AbortSignal.any([lifetime.signal,detailController.signal])});if(alive&&number===detailSequence&&modal.value&&target.value?.id===id&&applicationKey.value===key)detail.value=value}catch(e:any){if(alive&&number===detailSequence&&!detailController.signal.aborted)detailError.value=e.message||'详情读取失败'}finally{if(alive&&number===detailSequence)detailBusy.value=false}}
function leaveAction(next:()=>void){if(mutation.value)return;const move=()=>{action.value=null;actionTarget.value=null;reason.value='';next()};if(action.value&&reason.value.trim())discard.request(move);else move()}
function openDetail(row:Sale){leaveAction(()=>{target.value=row;detail.value=null;modal.value=true;void readDetail('row')})}
function chooseApplication(key:string){leaveAction(()=>{modal.value=false;detailSequence++;detailController?.abort();detail.value=null;applicationKey.value=key;page.value=1;void load('application')})}
function ask(value:'approve'|'reject'|'retry'){if(mutation.value||detailBusy.value||!permitted(value)||detail.value?.id!==target.value?.id)return;action.value=value;actionTarget.value={id:detail.value!.id,applicationKey:applicationKey.value};reason.value='';actionError.value=''}
function closeAction(){if(mutation.value)return;if(reason.value.trim())discard.request(()=>{action.value=null;reason.value='' });else action.value=null}
async function submit(){if(!action.value||!actionTarget.value||mutation.value)return;if(!permitted(action.value)||detail.value?.id!==actionTarget.value.id||applicationKey.value!==actionTarget.value.applicationKey){actionError.value='售后状态或权限已变化，请刷新详情';return}if(!reason.value.trim()){actionError.value='请填写处理原因';return}const mode=action.value,{id,applicationKey:key}=actionTarget.value;mutation.value=true;actionError.value='';try{await auth.api(endpoint+'/'+encodeURIComponent(key)+'/'+id+(mode==='retry'?'/retry':'/review'),'POST',{reason:reason.value.trim(),...(mode==='retry'?{}:{decision:mode})},{signal:lifetime.signal});if(!alive)return;action.value=null;actionTarget.value=null;reason.value='';await Promise.all([load('mutation'),readDetail('mutation')])}catch(e:any){if(alive)actionError.value=e.message||'处理结果未确认，请刷新原售后单核对'}finally{if(alive)mutation.value=false}}
watch(modal,open=>{if(!open){detailSequence++;detailController?.abort();detailBusy.value=false;detail.value=null}})
usePageLeaveGuard(()=>{if(mutation.value)return false;if(action.value&&reason.value.trim())return discard.decide(()=>{action.value=null;reason.value=''})})
useUnsavedBeforeUnload(()=>mutation.value||!!(action.value&&reason.value.trim()))
onBeforeUnmount(()=>{alive=false;listSequence++;detailSequence++;lifetime.abort();listController?.abort();detailController?.abort()})
</script>
<template><AdminConsole :refreshing="loadAction==='refresh'" @refresh="load('refresh')"><div class="space-y-5">
 <slot name="heading"><ConsolePageHeading title="订单管理"/></slot>
 <form @submit.prevent="filter('search')"><ConsoleListFilters><ConsoleListSearch v-model="q" placeholder="搜索售后、订单、支付编号或账号" :maxlength="100"/><USelect v-model="state" :items="[{value:'all',label:'全部售后状态'},...Object.entries(states).map(([value,label])=>({value,label}))]" aria-label="售后状态"/><USelect v-if="rows.providers" v-model="provider" :items="[{value:'all',label:'全部支付方式'},...rows.providers.map(p=>({value:p.key,label:p.label}))]" aria-label="支付方式"/><USelect v-if="rows.applications.length>1" :model-value="applicationKey" :disabled="mutation" :items="rows.applications.map(a=>({value:a.key,label:a.name}))" aria-label="业务应用" @update:model-value="chooseApplication"/><div class="flex shrink-0 items-center gap-3"><ConsoleQueryButton type="submit" :loading="loadAction==='search'">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="loadAction==='reset'" @click="filter('reset')">重置</ConsoleQueryButton></div></ConsoleListFilters></form>
 <ConsoleDataTable :data="rows.items" :columns="columns" :page="page" :page-size="pageSize" :page-size-items="[10,20,50]" :total="rows.total" :client-pagination="false" :error="error" empty-title="暂无售后订单" empty-description="用户提交退款申请或后台发起退款后会显示在这里。" min-table-width="1100px" @retry="load('retry')" @update:page="setPage" @update:page-size="setPageSize">
  <template #errorActions><UButton :loading="loadAction==='retry'" @click="load('retry')">重试</UButton></template>
  <template #id-cell="{row}"><span class="block max-w-40 truncate font-mono text-xs" :title="row.original.id">{{row.original.id}}</span><span class="mt-1 block max-w-40 truncate font-mono text-xs text-muted" :title="row.original.orderId">{{row.original.orderId}}</span></template>
  <template #providerLabel-cell="{row}"><span class="whitespace-nowrap">{{row.original.providerLabel||'历史未记录'}}</span><span v-if="row.original.paymentId" class="mt-1 block text-xs text-muted">第 {{row.original.paymentSequence}} 次 · {{row.original.currentPayment?'当前支付':'已切换'}}</span></template>
  <template #user-cell="{row}"><ConsumerIdentity :user-id="row.original.user.id" :profile="row.original.user"/></template>
  <template #source-cell="{row}">{{sources[row.original.source]||row.original.source}}<span v-if="row.original.previousId" class="block text-xs text-muted">重试记录</span></template>
  <template #state-cell="{row}"><UBadge color="neutral" variant="subtle">{{states[row.original.state]||row.original.state}}</UBadge></template>
  <template #requestedCents-cell="{row}"><p class="whitespace-nowrap">申请 {{money(row.original.requestedCents)}}</p><p class="mt-1 whitespace-nowrap text-xs text-muted">实退 {{refunded(row.original)}}</p></template>
  <template #createdAt-cell="{row}"><span class="whitespace-nowrap text-xs">{{dateTime(row.original.createdAt)}}</span></template>
  <template #actions-cell="{row}"><UButton variant="link" size="sm" class="px-0" :loading="detailBusy&&detailSource==='row'&&target?.id===row.original.id" @click="openDetail(row.original)">查看详情</UButton></template>
 </ConsoleDataTable>
 <ConsoleDrawer v-model:open="modal" title="售后订单详情" :dismissible="!mutation&&!action" :close="!mutation&&!action"><template #body><UAlert v-if="detailError" color="error" :title="detailError"><template #actions><UButton :loading="detailBusy&&detailSource==='retry'" @click="readDetail('retry')">重试</UButton></template></UAlert><p v-if="detailBusy&&!detail" role="status" class="text-sm text-muted">正在读取售后订单…</p><div v-if="detail" class="drawer-detail space-y-6">
  <section class="space-y-4"><div class="flex items-center justify-between gap-3"><UBadge color="neutral" variant="subtle">{{states[detail.state]}}</UBadge><UButton color="neutral" variant="outline" :disabled="mutation||detailBusy" @click="readDetail('refresh')"><template #leading><UIcon name="i-lucide-refresh-cw" class="size-4" :class="{'animate-spin':detailBusy&&detailSource==='refresh'}"/></template>刷新状态</UButton></div><ConsumerIdentity :user-id="detail.user.id" :profile="detail.user"/><UAlert v-if="detail.state==='APPLIED'&&!detail.canApprove&&detail.approveUnavailableReason" color="warning" variant="subtle" :ui="{title:'text-highlighted',description:'text-toned'}" title="当前不能同意退款" :description="detail.approveUnavailableReason"/><dl class="drawer-facts"><dt>售后编号</dt><dd class="break-all">{{detail.id}}</dd><dt>原订单</dt><dd class="break-all">{{detail.orderId}}</dd><dt>购买内容</dt><dd>{{detail.orderName||'待核查'}}</dd><dt>支付方式</dt><dd>{{detail.providerLabel||'历史未记录'}}</dd><dt>支付编号</dt><dd class="break-all">{{detail.paymentId||'—'}}</dd><dt>支付记录</dt><dd>{{detail.paymentId?'第 '+detail.paymentSequence+' 次 · '+(detail.currentPayment?'当前支付':'已切换的历史支付'):'—'}}</dd><dt>来源</dt><dd>{{sources[detail.source]}}</dd><dt>申请退款金额</dt><dd>{{money(detail.requestedCents)}}<span v-if="detail.legacyFullRefund" class="ml-2 text-xs text-muted">历史整单申请</span></dd><dt>原支付实付</dt><dd>{{money(detail.payerTotalCents)}}</dd><dt>原支付累计实退</dt><dd>{{money(detail.payerRefundedCents)}}</dd><dt>剩余可申请金额</dt><dd>{{money(detail.remainingRequestedCents)}}</dd><dt>{{detail.source==='consumer'?'申请原因':'退款原因'}}</dt><dd class="whitespace-pre-wrap">{{detail.reason}}</dd><dt>申请时间</dt><dd>{{dateTime(detail.createdAt)}}</dd><dt>审核原因</dt><dd class="whitespace-pre-wrap">{{detail.reviewReason||(detail.source==='consumer'&&detail.state==='APPLIED'?'尚未审核':'—')}}</dd><dt>审核时间</dt><dd>{{dateTime(detail.reviewedAt)}}</dd><dt>本次实际退款</dt><dd>{{refunded(detail)}}</dd><dt>退款成功时间</dt><dd>{{dateTime(detail.state==='SUCCESS'?detail.succeededAt:null)}}</dd></dl></section>
  <section class="space-y-2"><h3 class="drawer-section-title">资产处理</h3><p class="text-sm leading-6 text-muted">{{detail.refundEffect}}</p></section>
  <section v-if="detail.history.length>1"><h3 class="drawer-section-title">本次支付的售后记录</h3><ol class="mt-4 space-y-4"><li v-for="item in detail.history" :key="item.id" class="border-t border-default pt-3 text-sm"><div class="flex flex-wrap justify-between gap-2"><span>第 {{item.sequence}} 条 · {{states[item.state]}}</span><span class="text-xs text-muted">{{dateTime(item.createdAt)}}</span></div><p class="mt-1 break-all text-xs text-muted">{{item.id}}</p><p class="mt-2">申请 {{money(item.requestedCents)}} · 实退 {{refunded(item)}}</p><p v-if="item.state==='SUCCESS'" class="mt-1 text-xs text-muted">退款成功 {{dateTime(item.succeededAt)}}</p><p v-if="item.reviewReason" class="mt-1">{{item.reviewReason}}</p></li></ol></section>
  <UAlert v-if="detail.state==='CLOSED'" color="warning" variant="subtle" :ui="{title:'text-highlighted',description:'text-toned'}" title="退款已关闭" :description="detail.canRetry?'核验并重试会先查询原渠道，确认关闭且未退款后才创建后续退款任务。':detail.retryUnavailableReason||'请核查原退款结果。'"/>
  <UAlert v-else-if="detail.lastError" color="warning" variant="subtle" :ui="{title:'text-highlighted',description:'text-toned'}" title="退款结果待核查" description="请核查原交易；处理中或结果不明时不能重复发起另一笔退款。"/>
 </div></template><template #footer><div class="flex w-full justify-end gap-3"><UButton v-if="detail?.canReject" color="neutral" variant="outline" :disabled="mutation||detailBusy" @click="ask('reject')">拒绝申请</UButton><UButton v-if="detail?.canReview" color="primary" :disabled="mutation||detailBusy||!detail.canApprove" @click="ask('approve')">同意退款</UButton><UButton v-if="detail?.canRetry" color="error" variant="outline" :disabled="mutation||detailBusy" @click="ask('retry')">核验并重试退款</UButton></div></template></ConsoleDrawer>
 <UModal :open="!!action" :title="actionTitle" :description="action==='reject'?'拒绝后不会调用支付渠道，也不会回收原订单资产。':action==='approve'?(detail?.refundEffect||'请刷新原订单处理规则。')+' 按申请金额原路退款；受理不代表资金已退回。':'先核验原渠道退款结果，再提交新的退款任务；原退款记录会完整保留。'" :dismissible="!mutation" :close="!mutation" @update:open="(value:boolean)=>{if(!value)closeAction()}"><template #body><UFormField label="处理原因" required><UTextarea v-model="reason" :maxlength="200" :disabled="mutation" class="w-full"/></UFormField><UAlert v-if="actionError" class="mt-4" color="error" :title="actionError"/></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" :disabled="mutation" @click="closeAction">取消</UButton><UButton :loading="mutation" :disabled="mutation||!action||!permitted(action)" @click="submit">确认{{action==='reject'?'拒绝':action==='approve'?'同意':'重试'}}</UButton></div></template></UModal>
 <ConsoleDiscardChangesDialog :controller="discard"/>
</div></AdminConsole></template>
